-- =============================================================================
-- DEMO DATA: FOR ILLUSTRATION ONLY
--
-- Every listing below is fictitious. Titles are prefixed "[DEMO]", rows are
-- flagged is_demo = true, the UI labels them as demo listings, enquiries are
-- disabled for them (enforced in submit_enquiry), they are excluded from search
-- indexing, and no seller account is attached.
--
-- Verification states on demo listings come from demo verification records
-- (is_demo = true, no reviewer). They are shown in the UI as "Demo" states and
-- do not represent any real check.
--
-- Remove all demo data with: supabase/scripts/remove-demo-data.sql
-- =============================================================================

begin;

create temporary table demo_listing (
  title text, summary text, description text, category_slug text, jurisdiction_slug text,
  transaction_type public.transaction_type, operating_status public.operating_status,
  asking_price numeric, currency text, price_on_request boolean, licence_type text, regulator text,
  year_established int, team_size text, revenue_range text, included_assets text[], highlights text[],
  verification public.verification_level, verified_days_ago int, is_featured boolean,
  status public.asset_status, published_days_ago int
);

