insert into public.assets (
  title, summary, description, category_id, jurisdiction_id, transaction_type, operating_status,
  asking_price, currency, price_on_request, licence_type, regulator, year_established, team_size,
  revenue_range, included_assets, highlights, is_demo, is_featured, status, approved_at, published_at, sold_at
)
select d.title, d.summary, d.description, c.id, j.id, d.transaction_type, d.operating_status,
       d.asking_price, d.currency, d.price_on_request, d.licence_type, d.regulator, d.year_established,
       d.team_size, d.revenue_range, d.included_assets, d.highlights, true, d.is_featured, d.status,
       now() - make_interval(days => d.published_days_ago + 1),
       now() - make_interval(days => d.published_days_ago),
       case when d.status = 'sold' then now() - make_interval(days => greatest(d.published_days_ago - 30, 1)) end
  from demo_listing d
  join public.categories c on c.slug = d.category_slug
  join public.jurisdictions j on j.slug = d.jurisdiction_slug
 where not exists (select 1 from public.assets a where a.title = d.title);

-- Illustrative verification records (is_demo = true, no reviewer). The sync
-- trigger derives each demo listing's displayed state from these records.
insert into public.verification_records (asset_id, level, method, source_reference, notes, reviewer_id, checked_at, is_demo)
select a.id, d.verification,
       'DEMO record: illustrative only, no check performed',
       null,
       'Demo data. This record exists only to demonstrate how verification states are displayed.',
       null,
       now() - make_interval(days => d.verified_days_ago),
       true
  from demo_listing d
  join public.assets a on a.title = d.title and a.is_demo
 where d.verification <> 'unverified'
   and not exists (select 1 from public.verification_records v where v.asset_id = a.id);

drop table demo_listing;

commit;
